"""RO-style equipment slots. One coherent generated body/outfit; no limb scaling."""
from pathlib import Path
import base64,json,hashlib
P=Path(__file__).resolve().parent;ROOT=P.parents[2]
def bind(f):return dict(path=str(f.relative_to(ROOT)),sha256=hashlib.sha256(f.read_bytes()).hexdigest())
body=P/'body-halo-raw.png';heads={s:P.parent/'hair-swap-v33'/('head-'+s+'.png') for s in ['original','silver','auburn','bald']}
scale=300/(1430-225);body_matrix=[scale,0,0,scale,250-scale*434,180-scale*225];head_matrix=[.40,0,0,.40,250-.40*202,180-.40*326]
contract=dict(schema='body-outfit-slots-v1',canvas=[512,512],view='A_LEFT_THREE_QUARTER_NEUTRAL_CANDIDATE',action='neutral_proportion_study',pose_count=1,body=dict(slot='body_outfit',file=bind(body),matrix=body_matrix,includes=['torso','both_arms','both_hands','hips','both_legs','both_boots','armor','belt','tabards','scarf','cape'],independent_limb_transform_allowed=False),head=dict(slot='head_style',matrix=head_matrix,variants={s:bind(f) for s,f in heads.items()},source_mount=[202,326],target_mount=[250,180]),other_supported_slots=[],proposed_slots=['headgear','weapon','shield','optional_back_accessory'],no_mirroring=True,body_scale_policy='one uniform scale for the complete outfit, authored once in rest',head_scale_policy='one shared scale for complete head-style cache; no runtime independent hair/eye resize',outfit_change_policy='select another complete compatible body/action/view bank; never silently replace one sleeve',animation_approval=False,user_proportion_approved=False,production_pass=False)
contract['head']['size_matrices']={'corrected':head_matrix,'before':[.45,0,0,.45,250-.45*202,180-.45*326]}
contract['head']['size_change']={'user_feedback':'ขนาดหัวมันใหญ่ไปหน่อยมั้ย','previous_scale':.45,'current_scale':.40,'linear_reduction_fraction':1-.40/.45,'same_neck_mount':True,'body_matrix_unchanged':True}
(P/'slot-contract.json').write_text(json.dumps(contract,indent=2)+'\n')
images={'body':'data:image/png;base64,'+base64.b64encode(body.read_bytes()).decode(),**{s:'data:image/png;base64,'+base64.b64encode(f.read_bytes()).decode() for s,f in heads.items()}}
html='''<!doctype html><meta charset="utf-8"><title>Body + outfit / proportion study</title><style>body{background:#1d2935;color:#eef1fc;font:16px system-ui;margin:24px}canvas{width:512px;height:512px;background:#344351}button,select{font:inherit}p{max-width:850px}</style><h1>Body + outfit / neutral proportion study</h1><canvas id="view" width="512" height="512"></canvas><p><select id="head"><option value="original">Original combined head</option><option value="silver">Silver head style</option><option value="auburn">Auburn head style</option><option value="bald">Bald base</option></select><select id="background"><option value="#344351">Slate</option><option value="#ffffff">White</option><option value="#0c1421">Dark</option></select><label><input id="body-only" type="checkbox">Body + outfit only</label></p><p>One coherent clothed body and one complete head style. Single neutral pose for proportion review.</p><script>
const CONTRACT=__CONTRACT__,DATA=__IMAGES__,images={},ctx=document.getElementById('view').getContext('2d');let ready=false,style='original';
Promise.all(Object.entries(DATA).map(([n,src])=>new Promise(resolve=>{const im=new Image;im.onload=()=>{images[n]=im;resolve()};im.src=src}))).then(()=>{ready=true;draw()});
function draw(s=style,bodyOnly=document.getElementById('body-only').checked,size=document.getElementById('head-size').value){if(!ready)return;if(!CONTRACT.head.size_matrices[size])throw Error('Unsupported head size');ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,512,512);ctx.setTransform(...CONTRACT.body.matrix);ctx.drawImage(images.body,0,0);if(!bodyOnly){ctx.setTransform(...CONTRACT.head.size_matrices[size]);ctx.drawImage(images[s],0,0)}ctx.setTransform(1,0,0,1,0,0)}
document.getElementById('head').onchange=e=>{style=e.target.value;draw()};document.getElementById('body-only').onchange=()=>draw();document.getElementById('background').onchange=e=>ctx.canvas.style.background=e.target.value;
window.outfit={get ready(){return ready},contract:CONTRACT,frame(s='original',bodyOnly=false,size='corrected'){if(!CONTRACT.head.variants[s])throw Error('Unsupported head');draw(s,bodyOnly,size);return ctx.canvas.toDataURL('image/png')}};
</script>'''
html=html.replace('<select id="background">','<select id="head-size"><option value="corrected">Head reduced 11.1%</option><option value="before">Previous head size</option></select><select id="background">').replace("document.getElementById('head').onchange", "document.getElementById('head-size').onchange=()=>draw();document.getElementById('head').onchange")
(P/'outfit-preview.html').write_text(html.replace('__CONTRACT__',json.dumps(contract,separators=(',',':'))).replace('__IMAGES__',json.dumps(images,separators=(',',':'))))
